parameters.jsCode:
// Obtener información recibida desde el Webhook
const entrada = $input.first().json;

// El POST del Webhook viene dentro de body
const factura = entrada.body ?? entrada;

// Tarifario autorizado de prueba
const tarifario = {
  "REP-001": {
    descripcion: "Reparacion de parachoques",
    precio_maximo: 150
  },
  "PIN-001": {
    descripcion: "Pintura de pieza",
    precio_maximo: 120
  },
  "MO-001": {
    descripcion: "Mano de obra mecanica",
    precio_maximo: 45
  },
  "REP-002": {
    descripcion: "Reemplazo de faro",
    precio_maximo: 180
  }
};

// Variables de auditoria
const hallazgos = [];
const codigosProcesados = new Set();

let montoSobrecosto = 0;
let montoDuplicados = 0;

// Analizar los conceptos de la factura
for (const item of factura.items ?? []) {

  const codigo = item.codigo;
  const cantidad = Number(item.cantidad ?? 0);
  const precio = Number(item.precio_unitario ?? 0);

  // Validar existencia en tarifario
  if (!tarifario[codigo]) {

    hallazgos.push({
      tipo: "FUERA_TARIFARIO",
      codigo: codigo,
      descripcion: item.descripcion,
      detalle: "El concepto no existe en el tarifario autorizado"
    });

  } else {

    const precioPermitido = tarifario[codigo].precio_maximo;

    // Detectar sobrecostos
    if (precio > precioPermitido) {

      const diferencia = (precio - precioPermitido) * cantidad;

      montoSobrecosto += diferencia;

      hallazgos.push({
        tipo: "SOBRECOSTO",
        codigo: codigo,
        descripcion: item.descripcion,
        precio_facturado: precio,
        precio_maximo: precioPermitido,
        cantidad: cantidad,
        diferencia: diferencia
      });
    }
  }

  // Detectar posibles duplicados
  if (codigosProcesados.has(codigo)) {

    const impacto = precio * cantidad;

    montoDuplicados += impacto;

    hallazgos.push({
      tipo: "POSIBLE_DUPLICADO",
      codigo: codigo,
      descripcion: item.descripcion,
      cantidad: cantidad,
      precio_unitario: precio,
      impacto: impacto
    });

  } else {

    codigosProcesados.add(codigo);

  }
}

// Clasificacion inicial
let estado = "PREVALIDADA";
let riesgo = "BAJO";

if (hallazgos.length > 0) {
  estado = "REVISION_REQUERIDA";
  riesgo = "MEDIO";
}

if (
  hallazgos.some(
    h => h.tipo === "SOBRECOSTO" ||
         h.tipo === "POSIBLE_DUPLICADO"
  )
) {
  riesgo = "ALTO";
}

// Construir resultado
return [
  {
    json: {
      auditoria_id: "AUD-" + (factura.factura_id ?? "SIN-ID"),
      factura_id: factura.factura_id,
      siniestro_id: factura.siniestro_id,
      taller: factura.taller,

      estado: estado,
      riesgo: riesgo,

      resumen: {
        total_facturado: Number(factura.total_facturado ?? 0),
        cantidad_items: factura.items?.length ?? 0,
        cantidad_hallazgos: hallazgos.length,
        monto_sobrecosto: montoSobrecosto,
        monto_posible_duplicado: montoDuplicados,
        monto_total_observado: montoSobrecosto + montoDuplicados
      },

      hallazgos: hallazgos,

      requiere_revision_humana: hallazgos.length > 0
    }
  }
];
